import UIKit

/// Official photography and canonical catalogue ids, shared with the website's first journey.
/// No product render, stock level or collection story is generated by this component.
final class OfficialCollectionHero: UIView {
  init(open: @escaping (String) -> Void) {
    super.init(frame: .zero)
    rounded(SaliniBrand.featureRadius)
    backgroundColor = Palette.ink
    let image = UIImageView(image: UIImage(named: "official-paola-hero.jpg"))
    image.contentMode = .scaleAspectFill
    image.clipsToBounds = true
    image.isAccessibilityElement = false
    image.setContentHuggingPriority(.init(1), for: .vertical)
    image.setContentCompressionResistancePriority(.init(1), for: .vertical)
    pin(image)
    let shade = GradientView(colors: [UIColor.black.withAlphaComponent(0.60), UIColor.black.withAlphaComponent(0.55), UIColor.black.withAlphaComponent(0.10), UIColor.black.withAlphaComponent(0.50)], locations: [0, 0.45, 0.70, 1])
    pin(shade)
    let heading = label("Вода обретает\nформу.", 44, .regular, .white, serif: true)
    heading.accessibilityIdentifier = "unified.hero.title"
    let intro = stack([
      eyebrow("SALINI · L’ANIMA DELL’ACQUA", color: .white.withAlphaComponent(0.85)),
      heading,
      label("Итальянский характер.\nИскусство вашего пространства.", 14, .regular, .white),
    ], spacing: 20)
    intro.translatesAutoresizingMaskIntoConstraints = false
    addSubview(intro)
    let button = ActionButton("Открыть Paola", icon: "arrow.up.right", prominent: false) { open("9185") }
    button.configuration?.baseForegroundColor = Palette.ink
    button.accessibilityIdentifier = "unified.hero.open"
    let foot = stack([eyebrow("В ГЛАВНОЙ РОЛИ", color: .white.withAlphaComponent(0.8)), label("Paola 172", 27, .regular, .white, serif: true), button], spacing: 10)
    foot.translatesAutoresizingMaskIntoConstraints = false
    addSubview(foot)
    let minHeight = heightAnchor.constraint(greaterThanOrEqualToConstant: 540)
    minHeight.isActive = true
    let preferredHeight = heightAnchor.constraint(equalToConstant: 540)
    preferredHeight.priority = .defaultHigh
    preferredHeight.isActive = true
    NSLayoutConstraint.activate([
      intro.topAnchor.constraint(equalTo: topAnchor, constant: 32),
      intro.leadingAnchor.constraint(equalTo: leadingAnchor, constant: 24),
      intro.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -24),
      foot.topAnchor.constraint(greaterThanOrEqualTo: intro.bottomAnchor, constant: 100),
      foot.leadingAnchor.constraint(equalTo: leadingAnchor, constant: 24),
      foot.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -24),
      foot.bottomAnchor.constraint(equalTo: bottomAnchor, constant: -24),
    ])
  }
  required init?(coder: NSCoder) { fatalError() }
}

final class OfficialProductTile: UIView {
  init(product: CatalogProduct, open: @escaping () -> Void) {
    super.init(frame: .zero)
    let image = UIImageView()
    image.contentMode = .scaleAspectFit
    image.backgroundColor = SaliniBrand.soft
    image.rounded(SaliniBrand.cardRadius)
    image.height(230)
    CatalogImages.shared.image(for: product, maxPixel: 700) { [weak image] in image?.image = $0 }
    pin(stack([image, eyebrow(product.category.uppercased()), label(product.name, 25, .regular, serif: true), label(product.dimensions.text ?? "Размеры в карточке", 12, .regular, Palette.muted)], spacing: 10))
    let hit = UIButton(type: .custom)
    hit.addAction(UIAction { _ in open() }, for: .touchUpInside)
    hit.accessibilityLabel = product.name + ", " + (product.dimensions.text ?? "Размеры в карточке")
    hit.accessibilityIdentifier = "home.product." + product.id
    pin(hit)
    accessibilityElements = [hit]
  }
  required init?(coder: NSCoder) { fatalError() }
}

extension HomeController {
  func officialCatalogueEntry() -> UIView {
    let heading = stack([eyebrow("ЕДИНОЕ ПРОСТРАНСТВО SALINI"), label("Найдите свою форму.", 30, .regular, serif: true)], spacing: 10)
    let options = ["Ванны", "Раковины", "Мебель", "Зеркала"]
    let rows = stack([], spacing: 10)
    for pair in stride(from: 0, to: options.count, by: 2) {
      let buttons = options[pair..<min(pair + 2, options.count)].map { category -> UIView in
        ActionButton(category, icon: "arrow.up.right") { [weak self] in
          let catalog = CatalogController()
          catalog.initialCategory = category
          self?.navigationController?.pushViewController(catalog, animated: true)
        }
      }
      let row = stack(buttons, axis: .horizontal, spacing: 10)
      row.distribution = .fillEqually
      rows.addArrangedSubview(row)
    }
    return stack([heading, rows], spacing: 20)
  }
}
